package com.mfg.erp.service;import com.mfg.common.api.*;import com.mfg.common.integration.BusinessEventService;import com.mfg.common.exception.BizException;import com.mfg.erp.dto.ProductionOrderCommand;import com.mfg.erp.entity.*;import com.mfg.erp.repo.*;import com.mfg.mdm.entity.*;import com.mfg.mdm.repo.*;import com.mfg.mdm.service.MasterDataService;import com.mfg.security.config.CurrentUser;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class ProductionOrderService{private final ProductionOrderRepository repo;private final MaterialRepository materials;private final BomRepository boms;private final MasterDataService master;private final org.springframework.jdbc.core.JdbcTemplate db;private final BusinessEventService events;
 @Transactional public ProductionOrder create(ProductionOrderCommand c){if(repo.existsByProdOrderNo(c.prodOrderNo()))throw BizException.of(ErrorCode.MASTER_DATA_ALREADY_EXISTS,"生产订单号已存在");Material p=materials.findByMaterialCode(c.productCode()).orElseThrow(()->BizException.of(ErrorCode.MASTER_DATA_NOT_FOUND,"产品物料不存在"));master.assertConsumable(p,"ERP 生产订单");Bom b=boms.findCurrentByProduct(c.productCode()).orElseThrow(()->BizException.of(ErrorCode.MASTER_DATA_NOT_PUBLISHED,"该产品没有已发布的当前 BOM"));ProductionOrder o=new ProductionOrder();o.setProdOrderNo(c.prodOrderNo());o.setProductCode(p.getMaterialCode());o.setProductName(p.getMaterialName());o.setPlanQty(c.planQty());o.setUnitCode(c.unitCode());o.setPlanStartDate(c.planStartDate());o.setPlanFinishDate(c.planFinishDate());o.setBomCode(b.getBomCode());o.setBomVersion(b.getBomVersion());o.setCreatedBy(CurrentUser.usernameOrSystem());return repo.save(o);}
 @Transactional public ProductionOrder release(Long id){ProductionOrder o=repo.findById(id).orElseThrow(()->BizException.notFound("生产订单",id));if(!"CREATED".equals(o.getStatus()))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"只有已创建的生产订单可以下达");String kit=db.queryForObject("SELECT kit_status FROM src_erp.erp_prod_order WHERE id=?",String.class,id);if(!"READY".equals(kit))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"生产订单必须先通过齐套检查");o.setStatus("RELEASED");ProductionOrder saved=repo.save(o);events.publish("ERP.PRODUCTION_ORDER.RELEASED","erp","mes","PRODUCTION_ORDER",o.getProdOrderNo(),java.util.Map.of("productCode",o.getProductCode(),"planQty",o.getPlanQty()));return saved;}}
